suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(patchwork);library(scales)})
arg<-grep('^--file=',commandArgs(FALSE),value=TRUE);HERE<-dirname(normalizePath(sub('^--file=','',arg[1]),winslash='/'))
read_panel<-function(x){d<-read.csv(file.path(HERE,paste0('Supplementary_Fig18_Panel',x,'.csv')),colClasses=c(Combo='character'));write.csv(d,file.path(HERE,paste0('Supplementary_Fig18_Panel',x,'_Render_Data.csv')),row.names=FALSE);d}
theme_pub<-theme_classic(base_size=7,base_family='Arial')+theme(axis.title=element_text(size=7,face='bold'),axis.text=element_text(size=6,colour='black'),axis.line=element_line(linewidth=.18),axis.ticks=element_line(linewidth=.18),strip.background=element_blank(),strip.text=element_text(size=7,face='bold'),plot.tag=element_text(size=8,face='bold'),legend.position='bottom',legend.text=element_text(size=6),legend.title=element_text(size=7,face='bold'),legend.key.size=unit(3,'mm'),panel.spacing=unit(3,'mm'),plot.margin=margin(5,5,5,5,'pt'))
display_labs<-c('Fixed-catch stress test'='Fixed-catch target simulation','Constrained BAU'='Feasible-catch BAU','Quota only'='Quota only','Fuel only'='Fuel only','Combined'='Combined','C-type quota'='C-type quota')
cols<-c('Fixed-catch stress test'='#A0A0A0','Constrained BAU'='#222222','Quota only'='#0072B2','Fuel only'='#D55E00','Combined'='#009E73','C-type quota'='#CC79A7')
a<-read_panel('A_Annual')%>%group_by(Year,Pathway)%>%summarise(Median=median(GHG_Mt),Lower=quantile(GHG_Mt,.05),Upper=quantile(GHG_Mt,.95),.groups='drop')
write.csv(a,file.path(HERE,'Supplementary_Fig18_PanelA_Summary.csv'),row.names=FALSE)
pa<-ggplot(a,aes(Year,Median,colour=Pathway,fill=Pathway))+geom_ribbon(aes(ymin=Lower,ymax=Upper),alpha=.10,colour=NA,show.legend=FALSE)+geom_line(linewidth=.5)+scale_colour_manual(values=cols,labels=display_labs,limits=names(cols),drop=FALSE,guide=guide_legend(nrow=2,byrow=TRUE))+scale_fill_manual(values=cols,guide='none')+labs(tag='(a)',x=NULL,y=expression('Annual GHG (Mt CO'[2]*'e)'))+theme_pub
b<-read_panel('B_Reductions')%>%filter(Combo!='0000');b$Pathway<-factor(b$Pathway,levels=c('Quota only','Fuel only','Combined'));b$Max_Days<-factor(b$Max_Days,levels=c(365,280),labels=c('365 days','280 days'))
pb<-ggplot(b,aes(Pathway,Reduction_2050_pct,fill=Pathway))+geom_hline(yintercept=0,colour='grey65',linewidth=.2)+geom_boxplot(width=.55,outlier.size=.3,linewidth=.25)+facet_wrap(~Max_Days)+scale_fill_manual(values=cols,guide='none')+labs(tag='(b)',x=NULL,y='Paired 2050 reduction (%)')+theme_pub
c<-read_panel('C_Catch_GHG');c$GHG_Mt<-c$Cumulative_GHG_t/1e6
pc<-ggplot(c,aes(Cumulative_Fleet_Catch_Mt,GHG_Mt,colour=Pathway))+geom_point(size=1,alpha=.65)+scale_colour_manual(values=cols,limits=names(cols),drop=FALSE,guide='none')+labs(tag='(c)',x='Cumulative LL/PS catch (Mt)',y=expression('Cumulative GHG (Mt CO'[2]*'e)'))+theme_pub
d<-read_panel('D_Shapley')%>%filter(Metric=='Total_GHG_tCO2e');d$Lever<-factor(d$Lever,levels=c('Quota','Fuel','Refrigerant','Consolidation'))
pd<-ggplot(d,aes(Lever,Contribution_Mt,fill=Lever))+geom_hline(yintercept=0,colour='grey65',linewidth=.2)+geom_boxplot(width=.55,outlier.size=.3,linewidth=.25)+scale_fill_manual(values=c(Quota=unname(cols['Quota only']),Fuel=unname(cols['Fuel only']),Refrigerant='#CC79A7',Consolidation='#E69F00'),guide='none')+labs(tag='(d)',x=NULL,y=expression('Shapley contribution (Mt CO'[2]*'e)'))+theme_pub
fig<-(pa/pb/(pc|pd))+plot_layout(heights=c(1,1,1.05),guides='collect')&theme(legend.position='bottom')
for(ext in c('pdf','png','tiff')){opt<-list(filename=file.path(HERE,paste0('Supplementary_Fig18_Constrained_Baseline.',ext)),plot=fig,width=183,height=210,units='mm',bg='white');if(ext=='pdf')opt$device<-cairo_pdf;if(ext=='png')opt$dpi<-300;if(ext=='tiff'){opt$dpi<-900;opt$compression<-'lzw'};do.call(ggsave,opt)}
